import{_ as a,c as t,o,ag as r}from"./chunks/framework.C86mscM5.js";const b=JSON.parse('{"title":"Kubernetes","description":"","frontmatter":{},"headers":[],"relativePath":"devops/orchestration/kubernetes/index.md","filePath":"devops/orchestration/kubernetes/index.md","lastUpdated":1788689791000}'),n={name:"devops/orchestration/kubernetes/index.md"};function i(l,e,s,d,c,u){return o(),t("div",null,e[0]||(e[0]=[r('<h1 id="kubernetes" tabindex="-1"><a href="https://kubernetes.io/" target="_blank" rel="nofollow noopener noreferrer">Kubernetes</a> <a class="header-anchor" href="#kubernetes" aria-label="Permalink to &quot;[Kubernetes](https://kubernetes.io/)&quot;">​</a></h1><blockquote><p>Production-Grade Container Orchestration</p></blockquote><h2 id="what-is-kubernetes" tabindex="-1">What is Kubernetes? <a class="header-anchor" href="#what-is-kubernetes" aria-label="Permalink to &quot;What is Kubernetes?&quot;">​</a></h2><blockquote><p><a href="https://kubernetes.io/docs/concepts/overview/" target="_blank" rel="nofollow noopener noreferrer">Kubernetes</a>, also known as K8s, is an open-source system for automating deployment, scaling, and management of containerized applications.</p></blockquote><h2 id="kubernetes-生产必需项" tabindex="-1">Kubernetes 生产必需项 <a class="header-anchor" href="#kubernetes-生产必需项" aria-label="Permalink to &quot;Kubernetes 生产必需项&quot;">​</a></h2><h3 id="workload-与网络" tabindex="-1">Workload 与网络 <a class="header-anchor" href="#workload-与网络" aria-label="Permalink to &quot;Workload 与网络&quot;">​</a></h3><ul><li>无状态服务通常使用 Deployment，有稳定身份或持久存储需求时评估 StatefulSet。</li><li>Service 为 Pod 提供稳定入口；外部流量通过 Ingress 或 Gateway API 进入。</li><li>Job/CronJob 用于有限任务，DaemonSet 用于每节点代理。</li></ul><h3 id="配置与-secret" tabindex="-1">配置与 Secret <a class="header-anchor" href="#配置与-secret" aria-label="Permalink to &quot;配置与 Secret&quot;">​</a></h3><p>ConfigMap 保存非敏感配置，Secret 保存敏感值，但 Base64 不是加密。生产环境应启用静态加密、最小 RBAC，并评估外部 Secret 系统。配置变化是否自动生效应由应用和发布流程明确约定。</p><h3 id="探针" tabindex="-1">探针 <a class="header-anchor" href="#探针" aria-label="Permalink to &quot;探针&quot;">​</a></h3><ul><li><code>startupProbe</code> 保护慢启动应用，避免过早重启。</li><li><code>readinessProbe</code> 决定是否接收流量，不应把非关键外部依赖全部纳入。</li><li><code>livenessProbe</code> 只检测无法自行恢复的僵死状态，错误配置会制造重启风暴。</li></ul><h3 id="资源与扩缩容" tabindex="-1">资源与扩缩容 <a class="header-anchor" href="#资源与扩缩容" aria-label="Permalink to &quot;资源与扩缩容&quot;">​</a></h3><p>为容器设置合理的 CPU/内存 requests 和 limits，以历史监控数据校准。HPA 需要可靠指标和足够副本，不能替代容量规划。通过 PodDisruptionBudget 和反亲和性降低维护或单节点故障影响。</p><h3 id="发布与回滚" tabindex="-1">发布与回滚 <a class="header-anchor" href="#发布与回滚" aria-label="Permalink to &quot;发布与回滚&quot;">​</a></h3><p>使用滚动更新参数控制最大不可用和额外副本；发布后结合就绪状态、烟雾测试和 SLI 判断。<code>kubectl rollout undo</code> 只能恢复工作负载模板，配置、数据库和外部依赖仍需独立恢复策略。</p><h3 id="排障顺序" tabindex="-1">排障顺序 <a class="header-anchor" href="#排障顺序" aria-label="Permalink to &quot;排障顺序&quot;">​</a></h3><ol><li>查看 Deployment、ReplicaSet、Pod 和 Event 状态。</li><li>检查调度、镜像拉取、启动参数、探针和资源限制。</li><li>查看当前日志和上一次容器日志。</li><li>从 Service Endpoint、DNS、NetworkPolicy 到 Gateway 逐层验证网络。</li><li>对比最近部署、配置和依赖变更。</li></ol>',17)]))}const p=a(n,[["render",i]]);export{b as __pageData,p as default};
